head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDSTF05013.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    if (js_market == "6") {
        var url;
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=CODE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.listingcommonbiz.select.designadvser.all";
        dts_leadcom.DataID = encodeURI(url);
        dts_leadcom.reset();
    } else {
        //상장주선인
        dts_leadcom.DataID = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listLeadCom&For=''";
        dts_leadcom.Reset();
    }
    for (k = 1; k <= dts_leadcom.getTotalRow(); k++) {
        if (dts_leadcom.getCellData(k, "TEXT") == "") {
            //널값은 삭제
            $c.cp.removeRow(dts_leadcom, k);
        }
    }
    //alert("call");

};
scwin.fn_oldadd = function() {
    var arrOldValues = new Array();
    var vValue;
    var vText;
    var fr_getLead = $c.frame.path("../").fn_getLeadComNoStr;
    //alert("lead :"+lead.text);
    var vleadnm = fr_getLead();
    //alert("[vleadnm] :"+vleadnm);
    if (vleadnm != undefined) {
        arrOldValues = vleadnm.split(",");
    }
    //alert("arrOldValues :"+arrOldValues);

    for (var i = 0; i < arrOldValues.length; i++) {
        //arr배열의 length만큼 반복
        //alert("old :" +arrOldValues[i]+"\n");  //브라우져에 배열의 요소를 순서대로 찍는다.
        for (k = 1; k <= dts_leadcom.getTotalRow(); k++) {
            if (dts_leadcom.getCellData(k, "TEXT") == arrOldValues[i]) {
                //alert("dts_leadcom :"+ dts_leadcom.NameValue(k, "TEXT") + " arrOldValues: " +arrOldValues[i]+"\n");  //브라우져에 배열의 요소를 순서대로 찍는다.
                vValue = dts_leadcom.getCellData(k, "VALUE");
                vText = dts_leadcom.getCellData(k, "TEXT");
                var RowPosition = dts_selectleadcom.getTotalRow();
                dts_selectleadcom.insertRow();
                dts_selectleadcom.setCellData(RowPosition + 1, "VALUE", vValue);
                dts_selectleadcom.setCellData(RowPosition + 1, "TEXT", vText);
            }
        }
    }
};
scwin.fn_add = function() {
    var vValue = dts_leadcom.getCellData(dts_leadcom.getRowPosition(), "VALUE");
    var vText = dts_leadcom.getCellData(dts_leadcom.getRowPosition(), "TEXT");
    var RowPosition = dts_selectleadcom.getTotalRow();
    for (i = 1; i <= dts_selectleadcom.getTotalRow(); i++) {
        if (dts_selectleadcom.getCellData(i, "VALUE") == vValue) {
            return;
        }
    }
    dts_selectleadcom.insertRow();
    dts_selectleadcom.setCellData(RowPosition + 1, "VALUE", vValue);
    dts_selectleadcom.setCellData(RowPosition + 1, "TEXT", vText);
};
scwin.fn_del = function() {
    //var RowPos = dts_selectleadcom.ValueRow(dts_selectleadcom.RowPosition, MTr_2.ItemText);
    var RowPos = dts_selectleadcom.getRowPosition();
    $c.cp.removeRow(dts_selectleadcom, RowPos);
};
scwin.fn_confirm = async function() {
    var vValue;
    var vText;
    for (i = 1; i <= dts_selectleadcom.getTotalRow(); i++) {
        if (i == 1) {
            vValue = dts_selectleadcom.getCellData(i, "VALUE");
            vText = dts_selectleadcom.getCellData(i, "TEXT");
        } else {
            vValue = vValue + "," + dts_selectleadcom.getCellData(i, "VALUE");
            vText = vText + "," + dts_selectleadcom.getCellData(i, "TEXT");
        }
    }

    //alert("vText :"+vText);
    var fr_setLead = $c.frame.path("../").fn_setLeadComNMStr;
    fr_setLead(vValue, vText);
    await $c.frame.CloseFrame();
};
scwin.grd_leadcom_OnDblClick = function(row, colid) {
    scwin.fn_add();
};
scwin.grd_selectleadcom_OnDblClick = function(row, colid) {
    scwin.fn_del();
};
scwin.img_rightarr_onclick = function() {
    scwin.fn_add();
};
scwin.img_leftarr_onclick = function() {
    scwin.fn_del();
};
scwin.btn_confirm_onclick = function() {
    scwin.fn_confirm();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_leadcom_OnLoadError = function() {
    $c.stf.alert_error(dts_leadcom);
};
scwin.dts_leadcom_OnFail = function() {
    $c.stf.alert_error(dts_leadcom);
};
scwin.dts_selectleadcom_OnLoadError = function() {
    $c.stf.alert_error(dts_selectleadcom);
};
scwin.dts_selectleadcom_OnFail = function() {
    $c.stf.alert_error(dts_selectleadcom);
};
scwin.gform_bak_onload = function() {
    gform.scroll = "no";
    //dts_leadcom.dataid ="menu.csv";
    dts_leadcom.dataid = "../service/ui/JUI103_S01.jsp";
    dts_leadcom.reset();
    dts_leadcom.sort("+PAGE_TEXT", 0);
    //dts_leadcom.sort(); // W-Craft 주석처리 


    //	var vHeadString="PAGE_VALUE:STRING(9),PAGE_TEXT:STRING(20)";
    //	dts_selectleadcom.SetDataHeader(vHeadString);

    dts_selectleadcom.dataid = "../service/ui/JUI200_S01.jsp";
    dts_selectleadcom.reset();
    //alert(dts_selectleadcom.dataid);

};
scwin.gform_onload = function() {
    gform.scroll = "no";
    //dts_leadcom.dataid ="menu.csv";
    //dts_leadcom.dataid ="../service/ui/JUI103_S01.jsp";
    //dts_leadcom.reset();
    if (js_market == "6") {
        $c.cm.setColumnProp(grd_leadcom, "TEXT", "Name", "지정자문인명");
        $c.cm.setColumnProp(grd_selectleadcom, "TEXT", "Name", "지정자문인명");
    }
    scwin.fn_list_sync();
    dts_leadcom.sort("+TEXT", 0);
    //dts_leadcom.sort(); // W-Craft 주석처리 
    var vHeadString = "VALUE:STRING(9),TEXT:STRING(100)";
    //dts_selectleadcom.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

    //dts_selectleadcom.addRow();
    scwin.fn_oldadd();
};
